class A:
    L = []
class B:
    def __init__(self):
        self.L = []
assert A().L is A().L
assert B().L is not B().L

calls = []
class Fox:
    def __init__(self, name, age):
        calls.append((self, name, age))
f = Fox("Sly", 3)
assert calls == [(f, "Sly", 3)]

class Fox:
    def __init__(self, name):
        self.name = name
a, b = Fox("A"), Fox("B")
assert a.name == "A" and b.name == "B"

import types
class A:
    def f(self):
        pass
assert isinstance(A().f, types.MethodType)

class A:
    def describe(self):
        return self
a = A()
assert a.describe() is a

class A:
    def describe():
        pass
try:
    A().describe()
    assert False
except TypeError as e:
    assert '0 positional arguments but 1 was given' in str(e)

class Counter:
    def add(me, amount):
        return me
c = Counter()
assert c.add(2) is c
